import net.neoforged.neoforge.common.world.chunk.RegisterTicketControllersEvent;
import net.minecraft.server.level.TicketType;
import net.minecraft.world.level.ChunkPos;

NeoForge.EVENT_BUS.addListener((RegisterTicketControllersEvent event) -> {
    // Register custom ticket type
    TicketType<ChunkPos> myTicket = TicketType.create(
        new ResourceLocation(MODID, "my_ticket"),
        (a, b) -> a.equals(b),
        (a, b) -> a - b
    );

    // Use ticket to force load chunk
    world.getChunkSource().addTicket(myTicket, new ChunkPos(x, z), 1, new ChunkPos(x, z));
});
